}

{
  "key_insight": "The paper introduces a training-free, domain-aware calibration method that improves anomaly detection performance in data-scarce settings by balancing source and target domain scores using quantile calibration and cross-validated selection criteria.",
  "relevance_score": 2,
  "summary": "This paper focuses on anomalous sound detection in audio domains with limited labeled data, proposing a post-hoc calibration and model selection method that does not require retraining. It has no direct or transferable application to claims reserving, individual claim modeling, or probabilistic reserve forecasting in general insurance."
}

{
  "key_insight": "LSTMs can detect climate-driven structural breaks in loss reserving triangles and adapt reserves more accurately than traditional methods, especially in catastrophe-exposed jurisdictions.",
  "relevance_score": 9,
  "summary": "This paper investigates using LSTM networks to detect structural breaks in property insurance reserving caused by climate change, benchmarking against traditional methods like Chain Ladder and Bornhuetter-Ferguson on real regulatory data enriched with climate variables. It offers both empirical results and a theoretical framework for probabilistic performance guarantees, making it highly relevant to actuarial practice facing non-stationary risk environments."
}

{
  "key_insight": "The paper introduces a model-agnostic bootstrap method for macro-level claims reserving that strictly adheres to the conditioning principle, ensuring calibrated uncertainty estimates by holding the observed triangle fixed and only simulating allocation proportions.",
  "relevance_score": 9,
  "summary": "This paper proposes a novel bootstrap technique for aggregate claims reserving that respects the conditioning principle, yielding calibrated predictive distributions without re-estimating parameters or resampling data. It is directly applicable to Chain-Ladder, Bornhuetter-Ferguson, and Cape Cod methods, offering practical improvements in uncertainty quantification and diagnostic value for actuarial practice."
